-- Multi-salon ownership and managed barber workflow. All fixtures roll back.
begin;
create temp table manager_ids(key text primary key,id uuid);
insert into manager_ids values('owner','b21f0000-0000-4000-8000-000000000001'),('other','b21f0000-0000-4000-8000-000000000002'),('staff','b21f0000-0000-4000-8000-000000000003'),('customer','b21f0000-0000-4000-8000-000000000004');
insert into auth.users(id,email) select id,key||'-multi-fixture@example.invalid' from manager_ids;
create function pg_temp.mid(k text) returns uuid language sql stable as $$select id from pg_temp.manager_ids where key=k$$;
create function pg_temp.assert_manager(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end;$$;
create function pg_temp.manager_denied(statement text,expected text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=expected then return;end if;raise exception 'Expected %, got %: %',expected,sqlstate,sqlerrm;end;raise exception 'Unauthorized operation succeeded';end;$$;
do $$begin execute format('grant usage on schema %I to anon,authenticated',pg_my_temp_schema()::regnamespace::text);end;$$;
grant all on manager_ids to authenticated;
grant execute on function pg_temp.mid(text),pg_temp.assert_manager(boolean,text),pg_temp.manager_denied(text,text) to authenticated,anon;
set local role anon;
select pg_temp.manager_denied('select public.manager_state()','42501');
select pg_temp.manager_denied($q$select public.manager_command('profile','{}')$q$,'42501');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.mid('owner'))::text,true);
set local role authenticated;
insert into manager_ids values('salon1',gen_random_uuid()),('salon2',gen_random_uuid());
select public.manager_command('create_salon',jsonb_build_object('id',pg_temp.mid('salon1'),'name','First multi salon fixture','address','Akurana','service_name','Fixture haircut','duration_minutes',1,'price_min_minor',100000,'price_max_minor',140000,'opens_at','00:00','closes_at','23:59','weekdays',jsonb_build_array(0,1,2,3,4,5,6)));
select public.manager_command('create_salon',jsonb_build_object('id',pg_temp.mid('salon2'),'name','Second multi salon fixture','address','Akurana','service_name','Fixture haircut','duration_minutes',45,'price_min_minor',90000,'price_max_minor',140000,'opens_at','00:00','closes_at','23:59','weekdays',jsonb_build_array(0,1,2,3,4,5,6)));
select pg_temp.assert_manager(jsonb_array_length(public.manager_state()->'salons')=2,'One manager owns multiple salons');
select pg_temp.assert_manager(jsonb_array_length(public.barber_context())=0,'Creating a salon does not force a primary barber');
select pg_temp.assert_manager((public.manager_command('create_salon',jsonb_build_object('id',pg_temp.mid('salon1')))->>'id')::uuid=pg_temp.mid('salon1'),'Create retry uses the same salon');
insert into manager_ids select 'service1',(s->'services'->0->>'id')::uuid from jsonb_array_elements(public.manager_state()->'salons')s where s->>'id'=pg_temp.mid('salon1')::text;
insert into manager_ids select 'service2',(s->'services'->0->>'id')::uuid from jsonb_array_elements(public.manager_state()->'salons')s where s->>'id'=pg_temp.mid('salon2')::text;
insert into manager_ids values('barber1',gen_random_uuid()),('barber2',gen_random_uuid()),('barber3',gen_random_uuid());
select public.manager_command('create_barber',jsonb_build_object('id',pg_temp.mid('barber1'),'salon_id',pg_temp.mid('salon1'),'display_name','First chair','bio','First bio','experience_years',4,'specialities',jsonb_build_array('Fades'),'service_ids',jsonb_build_array(pg_temp.mid('service1'))));
select public.manager_command('create_barber',jsonb_build_object('id',pg_temp.mid('barber2'),'salon_id',pg_temp.mid('salon1'),'display_name','Second chair','specialities','[]'::jsonb,'service_ids',jsonb_build_array(pg_temp.mid('service1'))));
select public.manager_command('create_barber',jsonb_build_object('id',pg_temp.mid('barber3'),'salon_id',pg_temp.mid('salon2'),'display_name','Other salon chair','specialities','[]'::jsonb,'service_ids',jsonb_build_array(pg_temp.mid('service2'))));
select pg_temp.assert_manager(jsonb_array_length(public.barber_context())=3,'Owner can operate every created barber across salons');
select pg_temp.assert_manager((public.barber_state(pg_temp.mid('barber3'))->'salon'->>'id')::uuid=pg_temp.mid('salon2'),'Selected chair belongs to the correct salon');
select pg_temp.assert_manager(bookmyturn_private.can_upload_salon_media(pg_temp.mid('owner')||'/'||pg_temp.mid('salon1')||'/photo.jpg'),'Owner may upload own salon cover');
select pg_temp.assert_manager(bookmyturn_private.can_upload_barber_media(pg_temp.mid('owner')||'/'||pg_temp.mid('barber2')||'/photo.jpg'),'Owner may upload any own barber portrait');
select pg_temp.assert_manager(not bookmyturn_private.can_upload_salon_media(pg_temp.mid('owner')||'/bad/photo.jpg'),'Invalid media paths fail safely');
select pg_temp.manager_denied($q$select public.manager_command('barber',jsonb_build_object('id',pg_temp.mid('barber1'),'salon_id',pg_temp.mid('salon1'),'display_name','Invalid service mix','specialities','[]'::jsonb,'service_ids',jsonb_build_array(pg_temp.mid('service2'))))$q$,'P0001');
select public.manager_command('profile',jsonb_build_object('display_name','Fixture Manager','avatar_path',pg_temp.mid('owner')||'/photo.jpg'));
select pg_temp.assert_manager(public.manager_state()->'profile'->>'display_name'='Fixture Manager','Account profile persists privately');
select pg_temp.manager_denied($q$select public.manager_command('profile',jsonb_build_object('display_name','Wrong photo','avatar_path',pg_temp.mid('other')||'/photo.jpg'))$q$,'42501');
select pg_temp.manager_denied('select * from bookmyturn_private.manager_profiles','42501');
-- Operate a managed chair without an employee Auth account.
insert into manager_ids select 'queue',(public.barber_command(pg_temp.mid('barber2'),'walk_in',jsonb_build_object('request_key',gen_random_uuid(),'service_id',pg_temp.mid('service1'),'customer_name','Manager walk-in'))->>'id')::uuid;
insert into manager_ids select 'session',(public.barber_command(pg_temp.mid('barber2'),'start',jsonb_build_object('id',pg_temp.mid('queue'),'agreed_price_minor',120000,'price_agreed',true))->>'id')::uuid;
select public.barber_command(pg_temp.mid('barber2'),'finish_haircut',jsonb_build_object('id',pg_temp.mid('session'),'final_amount_minor',120000,'final_agreed',true));
select pg_temp.assert_manager((public.barber_state(pg_temp.mid('barber2'))->'performance'->>'today_count')::int=1,'Created chair completes real operational workflow');
select pg_temp.assert_manager((public.barber_state(pg_temp.mid('barber3'))->'performance'->>'today_count')::int=0,'Other salon totals stay separate');
-- Customers discover and book the managed barber on inherited salon hours.
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.mid('customer'))::text,true);
select pg_temp.assert_manager(exists(select 1 from jsonb_array_elements(public.customer_catalog()->'salons')s where s->>'id'=pg_temp.mid('salon2')::text),'Customer discovery includes the new salon');
insert into manager_ids select 'appointment',(public.customer_command('request_appointment',jsonb_build_object('salon_id',pg_temp.mid('salon2'),'service_id',pg_temp.mid('service2'),'barber_id',pg_temp.mid('barber3'),'starts_at',((now() at time zone 'Asia/Colombo')::date+1+'14:00'::time) at time zone 'Asia/Colombo','request_key',gen_random_uuid()))->>'id')::uuid;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.mid('owner'))::text,true);
select public.barber_command(pg_temp.mid('barber3'),'accept',jsonb_build_object('id',pg_temp.mid('appointment')));
select pg_temp.manager_denied($q$select public.manager_command('barber',jsonb_build_object('id',pg_temp.mid('barber3'),'salon_id',pg_temp.mid('salon2'),'display_name','Busy chair','is_active',false,'specialities','[]'::jsonb,'service_ids',jsonb_build_array(pg_temp.mid('service2'))))$q$,'P0001');
-- Another manager cannot see or change any of these salons or chairs.
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.mid('other'))::text,true);
select pg_temp.assert_manager(jsonb_array_length(public.manager_state()->'salons')=0,'Other manager sees no owned salons');
select pg_temp.assert_manager(public.manager_state()->'profile'->>'display_name'='','Other manager cannot read account profile');
select pg_temp.manager_denied($q$select public.manager_command('salon',jsonb_build_object('salon_id',pg_temp.mid('salon1'),'name','Stolen'))$q$,'42501');
select pg_temp.manager_denied($q$select public.barber_state(pg_temp.mid('barber2'))$q$,'42501');
select pg_temp.assert_manager(not bookmyturn_private.can_upload_barber_media(pg_temp.mid('other')||'/'||pg_temp.mid('barber2')||'/photo.jpg'),'Other manager cannot upload another salon barber photo');
reset role;
insert into bookmyturn_private.salon_memberships(salon_id,user_id,role,barber_id) values(pg_temp.mid('salon1'),pg_temp.mid('staff'),'barber',pg_temp.mid('barber1'));
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.mid('staff'))::text,true);
set local role authenticated;
select pg_temp.assert_manager(jsonb_array_length(public.barber_context())=1,'Employee still sees only their assigned chair');
select pg_temp.manager_denied($q$select public.barber_state(pg_temp.mid('barber2'))$q$,'42501');
select pg_temp.manager_denied($q$select public.manager_command('salon',jsonb_build_object('salon_id',pg_temp.mid('salon1'),'name','Staff cannot own'))$q$,'42501');
reset role;
update bookmyturn_private.salon_memberships set is_active=false where user_id=pg_temp.mid('owner') and salon_id=pg_temp.mid('salon1');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.mid('owner'))::text,true);
set local role authenticated;
select pg_temp.assert_manager(jsonb_array_length(public.manager_state()->'salons')=1,'Revoked salon disappears while other ownership remains');
select pg_temp.manager_denied($q$select public.barber_state(pg_temp.mid('barber2'))$q$,'42501');
reset role;
select 'PASS: manager account, multiple salons, teams, media scopes, customer booking and access isolation' result;
rollback;
